lo=np.floor(allxyz.min(0)-34).astype(int); hi=np.ceil(allxyz.max(0)+34).astype(int); shape=tuple((hi-lo+1).astype(int))
mask=np.ones(shape,bool)
t=time.time()
for a in atoms:
