    nid=np.full(lm.size,-1,np.int32); nid[flat]=np.arange(len(flat),dtype=np.int32); nid=nid.reshape(lm.shape)
    rows=[]; cols=[]; vals=[]
    for d,w in zip(deltas,weights):
        ss=[]; dd=[]
        for axis,step in enumerate(d):
            if step>=0: ss.append(slice(0,lm.shape[axis]-step)); dd.append(slice(step,lm.shape[axis]))
            else: ss.append(slice(-step,lm.shape[axis])); dd.append(slice(0,lm.shape[axis]+step))
        a=nid[tuple(ss)]; b=nid[tuple(dd)]; good=(a>=0)&(b>=0); i=a[good]; j=b[good]
        rows.extend((i,j)); cols.extend((j,i)); vals.extend((np.full(2*len(i),w),np.full(2*len(i),w)))
    n=len(pts)
