            else:
                rows.append(js); cols.append(np.full(len(js),tid,np.int32)); vals.append(r[js])
    rows=np.concatenate(rows); cols=np.concatenate(cols); vals=np.concatenate(vals)
    g=coo_matrix((vals,(rows,cols)),shape=(n+2,n+2)).tocsr()
